import {safeUrl} from './engine.js';

export function renderOpportunityWorkspace(p,{name,initials,status,escape:e,supporting='',contacts=''}={}){
  const source=safeUrl(p.source_url),example=p.origin==='example';
  const origin=example?'Fictional example':p.origin==='discovery'?'Discovered · review required':'Imported · review required';
  const heading=p.suppressed?'Contact is restricted':p.status==='fit'?'Ready for your review':p.status==='excluded'?'Outside this audience':'A closer look';
  const note=p.suppressed?'This record is marked do not contact.':p.status==='fit'?'Check the context, then decide whether to shortlist.':p.status==='excluded'?'Review the reasons below before making a decision.':'Inspect the source and fill the gaps before shortlisting.';
  return `<div class="opportunity-shell"><aside class="opportunity-context" aria-label="Opportunity context"><div class="opportunity-brand"><img src="favicon.svg" width="28" height="28" alt=""><span>PULL / OPPORTUNITY</span></div><span class="badge ${example?'example':'review'}">${origin}</span><div class="opportunity-identity"><span class="opportunity-monogram" aria-hidden="true">${e(initials)}</span><h2>${e(name)}</h2><p>${e(p.title||'Role not provided')}</p><strong>${e(p.company||'Company not provided')}</strong></div><dl class="opportunity-facts">${[['Location',p.location||p.country],['Industry',p.industry],['Team size',p.employees?`${p.employees} people`:'']].map(([label,value])=>`<div><dt>${label}</dt><dd>${e(value||'Not provided')}</dd></div>`).join('')}</dl><div class="opportunity-source"><span class="opportunity-caption">Original context</span><p>${e(p.search_match||p.source_excerpt||p.signal||'No supporting context supplied. Open the original source to check this record.')}</p>${source?`<a class="source-reference" href="${e(source)}" target="_blank" rel="noopener noreferrer"><span>${e(new URL(source).hostname)}</span><span>Open source ↗</span></a>`:'<p class="small-print">No valid source link supplied.</p>'}<small>${example?'Example only. No real person or business is represented.':p.discovered_at?`Retrieved ${e(new Date(p.discovered_at).toLocaleDateString())}. Check current details at the source.`:'A supplied reference is not independent verification.'}</small></div></aside><div class="opportunity-decision"><header class="dialog-header"><div><span class="opportunity-caption">Review opportunity</span><h2 id="dialog-title">${heading}</h2><p>${note}</p></div><button class="close-button" data-action="close" aria-label="Close prospect review">×</button></header><div class="dialog-body"><section class="opportunity-assessment"><div class="opportunity-section-heading"><h3>Audience fit</h3><span class="badge ${p.status}">${e(status)}</span></div>${p.checks.map(c=>`<div class="check-row"><span class="check-state ${c.state}" aria-hidden="true">${c.state==='pass'?'✓':c.state==='fail'?'×':'?'}</span><span>${e(c.label)}</span><small>${e(c.detail)}</small></div>`).join('')||'<p class="small-print">Define an audience criterion to assess fit.</p>'}<p class="small-print assessment-note">${p.matched} criteria matched. Fit does not establish buying intent.</p></section><section class="opportunity-evidence"><h3>What the evidence says</h3><p>${e(p.signal||p.source_excerpt||'No specific need or buying signal has been supplied.')}</p><p class="small-print">Signal date: ${e(p.signal_date||'Not provided')}. ${example?'Fictional context for exploring the workflow.':'Check the original source before outreach.'}</p>${p.reasons.length?`<div class="opportunity-flags"><strong>${p.reasons.length} ${p.reasons.length===1?'point':'points'} to review</strong><ul>${p.reasons.map(reason=>`<li>${e(reason)}</li>`).join('')}</ul></div>`:''}${supporting}</section>${contacts}</div><footer class="dialog-footer"></footer></div></div>`;
}
